"""Money arithmetic for invoices.

Amounts are strings, arithmetic is done in ``Decimal``, and every line is
rounded half-up to whole cents. An invoice total is the sum of the rounded
lines.
"""
from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal("0.01")


def _to_cents(amount):
    return amount.quantize(CENTS, rounding=ROUND_HALF_UP)


def line_total(qty, unit_price):
    return _to_cents(Decimal(str(qty)) * Decimal(str(unit_price)))


def total(lines):
    return sum((line_total(l["qty"], l["unit_price"]) for l in lines), Decimal("0.00"))

